def write_utf8(path, content):
    with Path(path).open('w', encoding='utf-8', newline='') as output:
        output.write(content)

def badge(t,c='purple'): return f'<span class="badge {c}">{t}</span>'
def btn(t,c='',href='#'): return f'<a class="btn {c}" href="{href}">{t}</a>'
def av(name):
    initials=''.join(x[0] for x in name.split()[:2])
    return f'<span class="mini">{initials}</span>'
def metric(label,value,foot,icon='◆',color='var(--primary)',soft='#f3ecff'):
    return f'<div class="card metric" style="--mc:{color};--ms:{soft}"><div class="m-top"><span class="m-label">{label}</span><span class="m-ico">{icon}</span></div><div class="m-value">{value}</div><div class="m-foot">{foot}</div></div>'
def card(title,desc,body,action=''):
    return f'<section class="card"><div class="card-h"><div><b>{title}</b><small>{desc}</small></div>{action}</div><div class="card-b">{body}</div></section>'
def toolbar(filters=('All Status','Department','Recruiter')):
    return '<div class="toolbar"><div class="searchbox">⌕&nbsp; Search records...</div>'+''.join(f'<div class="filter {"active" if i==0 else ""}">{x}⌄</div>' for i,x in enumerate(filters))+'<div class="filter">More Filters</div></div>'
def head(title,sub,actions=''):
    return f'<div class="head"><div><div class="eyebrow">RecruitFlow Workspace</div><h1>{title}</h1><div class="sub">{sub}</div></div><div class="actions">{actions}</div></div>'
def info(items): return '<div class="info">'+''.join(f'<div class="k">{k}</div><div class="v">{v}</div>' for k,v in items)+'</div>'
def timeline(items): return '<div class="timeline">'+''.join(f'<div class="tl"><b>{t}</b><small>{m}</small></div>' for t,m in items)+'</div>'
def alert(title,desc,kind='warn',icon='!'): return f'<div class="alert {kind}"><div class="aico">{icon}</div><div><b>{title}</b><small>{desc}</small></div></div>'
def tabs(active='Overview'): return '<div class="tabs">'+''.join(f'<div class="tab {"active" if x==active else ""}">{x}</div>' for x in ['Overview','Candidates','Pipeline','Interviews','Offers','Hire Management','Analytics','Activity'])+'</div>'
def field(label,value='',span='',select=False,textarea=False,required=False):
    cls=f'field {span}'
    req=' <span class="req">*</span>' if required else ''
    if textarea: ctrl=f'<textarea>{value}</textarea>'
    elif select: ctrl=f'<select><option>{value}</option></select>'
    else: ctrl=f'<input value="{escape(value,quote=True)}">'
    return f'<div class="{cls}"><label>{label}{req}</label>{ctrl}</div>'
def person(name,meta=''): return f'<div class="person">{av(name)}<div><div class="cell">{name}</div><div class="meta">{meta}</div></div></div>'
def simple_chart():
    return '''<div class="chart"><svg viewBox="0 0 600 200" preserveAspectRatio="none"><g stroke="#e8e3f2"><line x1="0" y1="40" x2="600" y2="40"/><line x1="0" y1="80" x2="600" y2="80"/><line x1="0" y1="120" x2="600" y2="120"/><line x1="0" y1="160" x2="600" y2="160"/></g><path d="M0 150 C70 125,90 140,145 105 S230 72,300 90 S390 45,450 65 S540 30,600 40" fill="none" stroke="#1d4ed8" stroke-width="4"/><path d="M0 150 C70 125,90 140,145 105 S230 72,300 90 S390 45,450 65 S540 30,600 40 L600 200 L0 200 Z" fill="rgba(29,78,216,.1)"/></svg></div>'''

