def shell(filename,title,body,dark=False,extra=''):
    nav=''
    for group,items in nav_groups.items():
        nav+=f'<div class="group">{group}</div>'
        for href,label,icon in items:
            nav+=f'<a class="{"active" if href==filename else ""}" href="{href}"><span class="ico">{icon}</span>{label}</a>'
    darkcls='dark' if dark else ''
    return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="../styles.css"></head><body class="{darkcls}"><div class="app"><aside class="sidebar"><div class="brand"><div class="mark">R</div><div><b>RecruitFlow</b><small>Talent Operations</small></div></div><div class="nav">{nav}</div><div class="user"><div class="avatar">AM</div><div><b>Ahmed Mahmoud</b><small>HR Manager</small></div></div></aside><header class="header"><div class="crumb">RecruitFlow › <b>{title}</b></div><div class="search">⌕&nbsp; Search candidates, vacancies, applications...</div><div class="actions">{btn('＋ Quick Add','primary','16_add_candidate.html')}<span class="btn">◐</span><span class="btn">●</span><div class="avatar">AM</div></div></header><main class="main"><div class="page">{body}</div></main></div>{extra}</body></html>'''

